app/globals.css:
@tailwind base;
@tailwind components;
@tailwind utilities;


@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 222.2 84% 4.9%;
    --card: 0 0% 100%;
    --card-foreground: 222.2 84% 4.9%;
    --popover: 0 0% 100%;
    --popover-foreground: 222.2 84% 4.9%;
    --primary: 43 84% 62%;
    --primary-foreground: 190 31% 7%;
    --secondary: 22 49% 51%;
    --secondary-foreground: 45 100% 95%;
    --muted: 210 40% 96.1%;
    --muted-foreground: 215.4 16.3% 46.9%;
    --accent: 43 84% 92%;
    --accent-foreground: 22 49% 26%;
    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 210 40% 98%;
    --border: 214.3 31.8% 91.4%;
    --input: 214.3 31.8% 91.4%;
    --ring: 43 84% 62%;
    --radius: 0.5rem;
    --chart-1: 12 76% 61%;
    --chart-2: 173 58% 39%;
    --chart-3: 197 37% 24%;
    --chart-4: 43 74% 66%;
    --chart-5: 27 87% 67%;

    /* Shared product color contract. Public, auth, and dashboard surfaces
       may vary in density, but must preserve these color meanings. */
    --product-canvas: #152027;
    --product-chrome: #19272f;
    --product-surface: #1d2d35;
    --product-surface-raised: #253943;
    --product-surface-warm: #2d444d;
    --product-border: #54707a;
    --product-border-subtle: #344a54;
    --product-text: #f7faf8;
    --product-text-muted: #d3ddd8;
    --product-text-soft: #a9b8b2;
    --product-text-faint: #7e9189;
    --product-brand: #2f7df6;
    --product-brand-strong: #5796ff;
    --product-brand-action: #2563eb;
    --product-brand-action-hover: #1d4ed8;
    --product-brand-soft: rgba(47, 125, 246, 0.16);
    --product-brand-glow: rgba(47, 125, 246, 0.26);
    --product-spruce: #2dd4bf;
    --product-spruce-soft: rgba(45, 212, 191, 0.14);
    --product-gold: #d7a84f;
    --product-gold-soft: rgba(215, 168, 79, 0.14);
    --product-warm: #c97855;
    --product-warm-soft: rgba(201, 120, 85, 0.14);
    --product-success: #2ec98a;
    --product-success-soft: rgba(46, 201, 138, 0.14);
    --product-warning: #f0ae3a;
    --product-warning-soft: rgba(240, 174, 58, 0.16);
    --product-danger: #ef6a6a;
    --product-danger-soft: rgba(239, 106, 106, 0.16);
    --product-info: #49c6e5;
    --product-info-soft: rgba(73, 198, 229, 0.14);
  }

  .dark {
    --background: 222.2 84% 4.9%;
    --foreground: 210 40% 98%;
    --card: 222.2 84% 4.9%;
    --card-foreground: 210 40% 98%;
    --popover: 222.2 84% 4.9%;
    --popover-foreground: 210 40% 98%;
    --primary: 43 84% 62%;
    --primary-foreground: 190 31% 7%;
    --secondary: 22 40% 28%;
    --secondary-foreground: 45 100% 95%;
    --muted: 217.2 32.6% 17.5%;
    --muted-foreground: 215 20.2% 65.1%;
    --accent: 22 38% 28%;
    --accent-foreground: 45 100% 95%;
    --destructive: 0 62.8% 30.6%;
    --destructive-foreground: 210 40% 98%;
    --border: 217.2 32.6% 17.5%;
    --input: 217.2 32.6% 17.5%;
    --ring: 43 84% 62%;
    --chart-1: 220 70% 50%;
    --chart-2: 160 60% 45%;
    --chart-3: 30 80% 55%;
    --chart-4: 280 65% 60%;
    --chart-5: 340 75% 55%;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* Modern Form UI Styles */
@layer components {
  .auth-shell {
    --auth-canvas: #dfe8eb;
    --auth-surface: #eef4f5;
    --auth-surface-raised: #ffffff;
    --auth-border: #9fb4bb;
    --auth-text: #132028;
    --auth-text-muted: #58707a;
    --auth-text-soft: #45606a;
    --auth-text-faint: #7f969f;
    --auth-brand: var(--product-brand);
    --auth-brand-strong: var(--product-brand-strong);
    --auth-brand-ink: var(--product-brand);
    --auth-brand-action: var(--product-brand-action);
    --auth-spruce: var(--product-spruce);
    --auth-spruce-ink: #178e83;
    --auth-gold: var(--product-gold);
    --auth-gold-ink: #8b6a20;
    --auth-warm: var(--product-warm);
    --auth-success: var(--product-success);
    --auth-warning: var(--product-warning);
    --auth-danger: var(--product-danger);
    --auth-info: var(--product-info);
    --primary: 221.2 83.2% 53.3%;
    --primary-foreground: 0 0% 100%;
    --ring: 221.2 83.2% 53.3%;
  }

  .dark .auth-shell {
    --auth-canvas: #0b1116;
    --auth-surface: #142129;
    --auth-surface-raised: var(--product-surface);
    --auth-border: var(--product-border-subtle);
    --auth-text: var(--product-text);
    --auth-text-muted: var(--product-text-muted);
    --auth-text-soft: var(--product-text-soft);
    --auth-text-faint: var(--product-text-faint);
    --auth-brand-strong: #8fb7ff;
    --auth-brand-ink: #8fb7ff;
    --auth-spruce-ink: #7de8dc;
    --auth-gold-ink: #f0c76a;
  }

  .auth-shell-grid {
    background-image:
      linear-gradient(color-mix(in srgb, var(--auth-brand) 7.5%, transparent) 1px, transparent 1px),
      linear-gradient(90deg, color-mix(in srgb, var(--auth-spruce) 7%, transparent) 1px, transparent 1px);
    background-size: 44px 44px;
  }

  .auth-shell-wash {
    background:
      linear-gradient(135deg, color-mix(in srgb, var(--auth-brand) 18%, transparent), transparent 36%),
      linear-gradient(315deg, color-mix(in srgb, var(--auth-spruce) 11%, transparent), transparent 34%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.58), transparent 44%);
  }

  .dark .auth-shell-wash {
    background:
      linear-gradient(135deg, color-mix(in srgb, var(--auth-brand) 13%, transparent), transparent 36%),
      linear-gradient(315deg, color-mix(in srgb, var(--auth-spruce) 8%, transparent), transparent 34%);
  }

  .auth-input {
    color: var(--auth-text, #132028) !important;
    background-color: rgba(255, 255, 255, 0.92) !important;
    caret-color: var(--auth-brand, #2f7df6);
    -webkit-text-fill-color: var(--auth-text, #132028) !important;
    color-scheme: light;
  }

  .auth-input::placeholder {
    color: #7f969f !important;
    -webkit-text-fill-color: #7f969f;
    opacity: 1;
  }

  .dark .auth-input {
    color: var(--auth-text, #ffffff) !important;
    background-color: rgba(15, 23, 29, 0.92) !important;
    caret-color: var(--auth-brand-strong, #8fb7ff);
    -webkit-text-fill-color: var(--auth-text, #ffffff) !important;
    color-scheme: dark;
  }

  .dark .auth-input::placeholder {
    color: #7f969f !important;
    -webkit-text-fill-color: #7f969f;
  }

  .auth-input:-webkit-autofill,
  .auth-input:-webkit-autofill:hover,
  .auth-input:-webkit-autofill:focus {
    color: var(--auth-text, #132028) !important;
    background-color: rgba(255, 255, 255, 0.94) !important;
    caret-color: var(--auth-brand, #2f7df6);
    -webkit-text-fill-color: var(--auth-text, #132028) !important;
    -webkit-box-shadow: 0 0 0 1000px rgba(255, 255, 255, 0.94) inset !important;
    transition: background-color 99999s ease-in-out 0s;
  }

  .dark .auth-input:-webkit-autofill,
  .dark .auth-input:-webkit-autofill:hover,
  .dark .auth-input:-webkit-autofill:focus {
    color: var(--auth-text, #ffffff) !important;
    background-color: rgba(15, 23, 29, 0.96) !important;
    caret-color: var(--auth-brand-strong, #8fb7ff);
    -webkit-text-fill-color: var(--auth-text, #ffffff) !important;
    -webkit-box-shadow: 0 0 0 1000px rgba(15, 23, 29, 0.96) inset !important;
  }

  .button-gold-chestnut {
    border: 1px solid rgba(47, 125, 246, 0.5);
    background: linear-gradient(135deg, #2563eb 0%, #2f7df6 100%);
    color: #ffffff;
    box-shadow: 0 14px 30px rgba(47, 125, 246, 0.22);
  }

  .button-gold-chestnut:hover {
    background: linear-gradient(135deg, #1d4ed8 0%, #2563eb 100%);
    color: #ffffff;
  }

  .button-gold-chestnut-secondary {
    border: 1px solid rgba(84, 112, 122, 0.58);
    background: rgba(24, 38, 45, 0.78);
    color: #f7faf8;
    box-shadow: 0 10px 24px rgba(6, 14, 18, 0.18);
  }

  .button-gold-chestnut-secondary:hover {
    border-color: rgba(47, 125, 246, 0.68);
    background: rgba(47, 125, 246, 0.16);
    color: #ffffff;
  }

  .button-gold-chestnut-outline {
    border: 1px solid rgba(47, 125, 246, 0.42);
    background: rgba(47, 125, 246, 0.08);
    color: #1d4ed8;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.45);
  }

  .button-gold-chestnut-outline:hover {
    border-color: rgba(47, 125, 246, 0.66);
    background: rgba(47, 125, 246, 0.14);
    color: #1e40af;
  }

  .button-gold-chestnut-ghost {
    color: #2563eb;
  }

  .button-gold-chestnut-ghost:hover {
    background: rgba(47, 125, 246, 0.12);
    color: #1d4ed8;
  }

  .button-gold-chestnut-link {
    color: #2563eb;
  }

  .button-gold-chestnut-link:hover {
    color: #1d4ed8;
  }

  .dark .button-gold-chestnut-outline,
  .dashboard-landing-theme .button-gold-chestnut-outline {
    border-color: rgba(87, 150, 255, 0.42);
    background: rgba(47, 125, 246, 0.14);
    color: #f7faf8;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }

  .dark .button-gold-chestnut-outline:hover,
  .dashboard-landing-theme .button-gold-chestnut-outline:hover {
    border-color: rgba(87, 150, 255, 0.66);
    background: rgba(47, 125, 246, 0.2);
    color: #ffffff;
  }

  .dark .button-gold-chestnut-ghost,
  .dashboard-landing-theme .button-gold-chestnut-ghost {
    color: #8fb7ff;
  }

  .dark .button-gold-chestnut-ghost:hover,
  .dashboard-landing-theme .button-gold-chestnut-ghost:hover {
    background: rgba(47, 125, 246, 0.16);
    color: #ffffff;
  }

  .dark .button-gold-chestnut-link,
  .dashboard-landing-theme .button-gold-chestnut-link {
    color: #8fb7ff;
  }

  .dashboard-landing-theme {
    --dash-canvas: var(--product-canvas);
    --dash-chrome: var(--product-chrome);
    --dash-surface: var(--product-surface);
    --dash-surface-raised: var(--product-surface-raised);
    --dash-surface-warm: var(--product-surface-warm);
    --dash-border: var(--product-border);
    --dash-border-subtle: var(--product-border-subtle);
    --dash-text: var(--product-text);
    --dash-text-muted: var(--product-text-muted);
    --dash-text-soft: var(--product-text-soft);
    --dash-text-faint: var(--product-text-faint);
    --dash-brand: var(--product-brand);
    --dash-brand-strong: var(--product-brand-strong);
    --dash-brand-soft: var(--product-brand-soft);
    --dash-spruce: var(--product-spruce);
    --dash-spruce-soft: var(--product-spruce-soft);
    --dash-gold: var(--product-gold);
    --dash-gold-soft: var(--product-gold-soft);
    --dash-warm: var(--product-warm);
    --dash-warm-soft: var(--product-warm-soft);
    --dash-success: var(--product-success);
    --dash-success-soft: var(--product-success-soft);
    --dash-warning: var(--product-warning);
    --dash-warning-soft: var(--product-warning-soft);
    --dash-danger: var(--product-danger);
    --dash-danger-soft: var(--product-danger-soft);
    --dash-info: var(--product-info);
    --dash-info-soft: var(--product-info-soft);
    --background: 201 30% 12%;
    --foreground: 120 18% 98%;
    --card: 199 29% 16%;
    --card-foreground: 120 18% 98%;
    --popover: 199 29% 16%;
    --popover-foreground: 120 18% 98%;
    --primary: 43 84% 62%;
    --primary-foreground: 190 31% 7%;
    --secondary: 195 30% 22%;
    --secondary-foreground: 120 18% 98%;
    --muted: 195 24% 24%;
    --muted-foreground: 156 11% 70%;
    --accent: 175 66% 50%;
    --accent-foreground: 204 26% 6%;
    --border: 194 23% 34%;
    --input: 194 23% 34%;
    --ring: 43 84% 62%;
    position: relative;
    isolation: isolate;
    overflow-x: hidden;
    background:
      radial-gradient(circle at 12% 8%, rgba(73, 198, 229, 0.15), transparent 26%),
      radial-gradient(circle at 88% 12%, rgba(215, 168, 79, 0.12), transparent 24%),
      linear-gradient(132deg, rgba(47, 125, 246, 0.13), transparent 28%, rgba(45, 212, 191, 0.1) 58%, transparent 78%),
      linear-gradient(145deg, var(--dash-canvas) 0%, var(--dash-chrome) 48%, #1d333a 100%);
    color: var(--dash-text);
  }

  .dashboard-landing-theme::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background-image:
      linear-gradient(rgba(170, 199, 207, 0.13) 1px, transparent 1px),
      linear-gradient(90deg, rgba(170, 199, 207, 0.13) 1px, transparent 1px);
    background-size: 42px 42px;
    mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.82), transparent 92%);
  }

  .dashboard-landing-theme::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background:
      linear-gradient(90deg, rgba(255, 255, 255, 0.03), transparent 22%, rgba(255, 255, 255, 0.018) 72%, transparent),
      linear-gradient(to bottom, rgba(21, 32, 39, 0), rgba(21, 32, 39, 0.34));
  }

  .bee-eater-dashboard-theme {
    --dash-canvas: #0d1517;
    --dash-chrome: #142326;
    --dash-surface: #173035;
    --dash-surface-raised: #213d41;
    --dash-surface-warm: #4a3025;
    --dash-border: #5e817b;
    --dash-border-subtle: #315259;
    --dash-text: #fff8e6;
    --dash-text-muted: #e5e7d7;
    --dash-text-soft: #b8c9bd;
    --dash-text-faint: #859a91;
    --dash-brand: #25bdd0;
    --dash-brand-strong: #67dce9;
    --dash-brand-soft: rgba(37, 189, 208, 0.18);
    --dash-spruce: #41ba79;
    --dash-spruce-soft: rgba(65, 186, 121, 0.16);
    --dash-gold: #f0c54d;
    --dash-gold-soft: rgba(240, 197, 77, 0.16);
    --dash-warm: #bf7145;
    --dash-warm-soft: rgba(191, 113, 69, 0.18);
    --dash-success: #46c77c;
    --dash-success-soft: rgba(70, 199, 124, 0.16);
    --dash-warning: #f2a641;
    --dash-warning-soft: rgba(242, 166, 65, 0.16);
    --dash-danger: #df6b5e;
    --dash-danger-soft: rgba(223, 107, 94, 0.16);
    --dash-info: #39c6e6;
    --dash-info-soft: rgba(57, 198, 230, 0.15);
    --background: 188 28% 8%;
    --foreground: 45 100% 95%;
    --card: 189 31% 15%;
    --card-foreground: 45 100% 95%;
    --popover: 189 31% 15%;
    --popover-foreground: 45 100% 95%;
    --primary: 43 84% 62%;
    --primary-foreground: 190 31% 7%;
    --secondary: 31 41% 22%;
    --secondary-foreground: 45 100% 95%;
    --muted: 181 22% 24%;
    --muted-foreground: 146 14% 75%;
    --accent: 43 83% 62%;
    --accent-foreground: 190 31% 7%;
    --border: 178 16% 44%;
    --input: 178 16% 44%;
    --ring: 43 84% 62%;
    background:
      linear-gradient(118deg, rgba(191, 113, 69, 0.22), transparent 25%, rgba(37, 189, 208, 0.18) 52%, transparent 78%),
      linear-gradient(88deg, rgba(240, 197, 77, 0.12), transparent 32%, rgba(65, 186, 121, 0.12) 72%, transparent),
      linear-gradient(180deg, var(--dash-canvas) 0%, var(--dash-chrome) 48%, #18363a 100%);
  }

  .bee-eater-dashboard-theme::before {
    background-image:
      linear-gradient(rgba(240, 197, 77, 0.08) 1px, transparent 1px),
      linear-gradient(90deg, rgba(37, 189, 208, 0.1) 1px, transparent 1px);
  }

  .bee-eater-dashboard-theme::after {
    background:
      linear-gradient(90deg, rgba(255, 248, 230, 0.038), transparent 22%, rgba(37, 189, 208, 0.04) 72%, transparent),
      linear-gradient(to bottom, rgba(13, 21, 23, 0), rgba(13, 21, 23, 0.42));
  }

  .bee-eater-dashboard-theme .dashboard-live-dot {
    background: var(--dash-gold);
    box-shadow: 0 0 0 5px rgba(240, 197, 77, 0.12);
  }

  .bee-eater-dashboard-theme .dashboard-button-create {
    border-color: color-mix(in srgb, var(--dash-brand) 62%, var(--dash-border));
    background: linear-gradient(135deg, var(--dash-brand), var(--dash-brand-strong));
    box-shadow: 0 16px 34px color-mix(in srgb, var(--dash-brand) 26%, transparent);
  }

  .bee-eater-dashboard-theme .dashboard-button-create:hover {
    border-color: color-mix(in srgb, var(--dash-brand-strong) 72%, var(--dash-border));
    background: linear-gradient(135deg, color-mix(in srgb, var(--dash-brand) 86%, black), var(--dash-brand-strong));
  }

  .bee-eater-dashboard-theme .dashboard-button-primary {
    border-color: color-mix(in srgb, var(--dash-brand) 62%, var(--dash-border));
    background: linear-gradient(135deg, var(--dash-brand), var(--dash-brand-strong));
    color: #ffffff;
    box-shadow: 0 16px 36px color-mix(in srgb, var(--dash-brand) 28%, transparent);
  }

  .bee-eater-dashboard-theme .dashboard-button-primary:hover {
    background: linear-gradient(135deg, color-mix(in srgb, var(--dash-brand) 86%, black), var(--dash-brand-strong));
    color: #ffffff;
  }

  .dashboard-landing-content {
    position: relative;
    z-index: 1;
  }

  .dashboard-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    border: 1px solid var(--dash-border-subtle);
    background: rgba(37, 57, 67, 0.74);
    color: var(--dash-text-soft);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    line-height: 1;
    text-transform: uppercase;
    padding: 0.48rem 0.66rem;
    border-radius: 999px;
  }

  .dashboard-live-dot {
    width: 0.44rem;
    height: 0.44rem;
    border-radius: 999px;
    background: var(--dash-spruce);
    box-shadow: 0 0 0 5px rgba(45, 212, 191, 0.12);
  }

  .dashboard-glass-panel,
  .dashboard-stat-card,
  .dashboard-table-shell {
    border: 1px solid var(--dash-border-subtle);
    background:
      linear-gradient(180deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.03)),
      rgba(29, 45, 53, 0.84);
    box-shadow: 0 22px 70px rgba(6, 14, 18, 0.24);
    backdrop-filter: blur(18px);
  }

  .dashboard-stat-card {
    border-radius: 0.5rem;
    background:
      linear-gradient(135deg, var(--stat-soft, rgba(47, 125, 246, 0.16)), transparent 48%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.105), rgba(255, 255, 255, 0.03)),
      rgba(31, 49, 57, 0.88);
    box-shadow:
      0 18px 50px rgba(5, 14, 19, 0.22),
      inset 0 1px 0 rgba(255, 255, 255, 0.075);
    transition: border-color 180ms ease, transform 180ms ease, background 180ms ease;
  }

  .dashboard-stat-card::after {
    content: "";
    position: absolute;
    inset: auto 0 0 0;
    height: 42%;
    pointer-events: none;
    background: radial-gradient(circle at 70% 100%, color-mix(in srgb, var(--stat-accent, var(--dash-brand)) 28%, transparent), transparent 62%);
    opacity: 0.72;
  }

  .dashboard-stat-card:hover {
    transform: translateY(-2px);
    border-color: var(--dash-border);
    background:
      linear-gradient(135deg, var(--stat-soft, rgba(47, 125, 246, 0.18)), transparent 42%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.13), rgba(255, 255, 255, 0.045)),
      rgba(39, 61, 70, 0.94);
  }
  .cash-drawer-dashboard .dashboard-glass-panel,
  .cash-drawer-dashboard .dashboard-stat-card {
    box-shadow:
      0 10px 28px rgba(5, 14, 19, 0.16),
      inset 0 1px 0 rgba(255, 255, 255, 0.055);
    backdrop-filter: blur(12px);
  }

  .cash-drawer-dashboard .dashboard-stat-card {
    background:
      linear-gradient(135deg, var(--stat-soft, rgba(47, 125, 246, 0.13)), transparent 58%),
      rgba(31, 49, 57, 0.88);
  }

  .cash-drawer-dashboard .dashboard-stat-card::after {
    opacity: 0.28;
  }

  .cash-drawer-dashboard .dashboard-stat-card:hover {
    transform: none;
    border-color: color-mix(in srgb, var(--stat-accent, var(--dash-brand)) 52%, var(--dash-border-subtle));
    background:
      linear-gradient(135deg, var(--stat-soft, rgba(47, 125, 246, 0.15)), transparent 54%),
      rgba(34, 53, 62, 0.92);
  }

  .cash-drawer-dashboard .dashboard-button-primary {
    box-shadow: 0 10px 24px color-mix(in srgb, var(--dash-brand) 22%, transparent);
  }

  .dashboard-control {
    border: 1px solid var(--dash-border-subtle);
    background: rgba(24, 38, 45, 0.76);
    color: var(--dash-text);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.055);
  }

  .dashboard-control::placeholder {
    color: var(--dash-text-faint);
  }

  .dashboard-control:focus,
  .dashboard-control:focus-visible {
    border-color: var(--dash-brand);
    outline: none;
    box-shadow: 0 0 0 3px rgba(47, 125, 246, 0.18);
  }

  .dashboard-top-button {
    border: 1px solid var(--dash-border-subtle) !important;
    background: rgba(24, 38, 45, 0.72) !important;
    color: var(--dash-text-muted) !important;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.055) !important;
  }

  .dashboard-top-button:hover {
