/* From Uiverse.io by SchawnnahJ */
.loader {
  position: relative;
  width: 2.5em;
  height: 2.5em;
  transform: rotate(165deg);
}

.loader:before,
.loader:after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  display: block;
  width: 0.5em;
  height: 0.5em;
  border-radius: 0.25em;
  transform: translate(-50%, -50%);
}

.loader:before {
  animation: before8 2s infinite;
}

.loader:after {
  animation: after6 2s infinite;
}

@keyframes before8 {
  0% {
    width: 0.5em;
    box-shadow: 1em -0.5em rgba(225, 20, 98, 0.75),
      -1em 0.5em rgba(111, 202, 220, 0.75);
  }

  35% {
    width: 2.5em;
    box-shadow: 0 -0.5em rgba(225, 20, 98, 0.75),
      0 0.5em rgba(111, 202, 220, 0.75);
  }

  70% {
    width: 0.5em;
    box-shadow: -1em -0.5em rgba(225, 20, 98, 0.75),
      1em 0.5em rgba(111, 202, 220, 0.75);
  }

  100% {
    box-shadow: 1em -0.5em rgba(225, 20, 98, 0.75),
      -1em 0.5em rgba(111, 202, 220, 0.75);
  }
}

@keyframes after6 {
  0% {
    height: 0.5em;
    box-shadow: 0.5em 1em rgba(61, 184, 143, 0.75),
      -0.5em -1em rgba(233, 169, 32, 0.75);
  }

  35% {
    height: 2.5em;
    box-shadow: 0.5em 0 rgba(61, 184, 143, 0.75),
      -0.5em 0 rgba(233, 169, 32, 0.75);
  }

  70% {
    height: 0.5em;
    box-shadow: 0.5em -1em rgba(61, 184, 143, 0.75),
      -0.5em 1em rgba(233, 169, 32, 0.75);
  }

  100% {
    box-shadow: 0.5em 1em rgba(61, 184, 143, 0.75),
      -0.5em -1em rgba(233, 169, 32, 0.75);
  }
}

/* Loader positioning - specific to loading components */
.centered-loader {
  position: absolute;
  top: calc(50% - 1.25em);
  left: calc(50% - 1.25em);
}

/* Enhanced Progress Bar Styles */
.progress-full > div {
  background: linear-gradient(90deg, #10b981, #059669);
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.3);
}

.progress-high > div {
  background: linear-gradient(90deg, #3b82f6, #2563eb);
  box-shadow: 0 2px 8px rgba(59, 130, 246, 0.3);
}

.progress-medium > div {
  background: linear-gradient(90deg, #f59e0b, #d97706);
  box-shadow: 0 2px 8px rgba(245, 158, 11, 0.3);
}

.progress-low > div {
  background: linear-gradient(90deg, #ef4444, #dc2626);
  box-shadow: 0 2px 8px rgba(239, 68, 68, 0.3);
}

/* Animated gradient progress bars */
@keyframes progressPulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.8;
  }
}

.progress-full > div,
.progress-high > div,
.progress-medium > div,
.progress-low > div {
  animation: progressPulse 2s infinite;
}

/* Dashboard card hover effects */
.dashboard-card {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.dashboard-card:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
}

/* Trend badge glow effects */
.trend-badge-positive {
  box-shadow: 0 0 20px rgba(16, 185, 129, 0.3);
  animation: glowPositive 2s infinite;
}

.trend-badge-negative {
  box-shadow: 0 0 20px rgba(239, 68, 68, 0.3);
  animation: glowNegative 2s infinite;
}

@keyframes glowPositive {
  0%, 100% {
    box-shadow: 0 0 20px rgba(16, 185, 129, 0.3);
  }
  50% {
    box-shadow: 0 0 30px rgba(16, 185, 129, 0.5);
  }
}

@keyframes glowNegative {
  0%, 100% {
    box-shadow: 0 0 20px rgba(239, 68, 68, 0.3);
  }
  50% {
    box-shadow: 0 0 30px rgba(239, 68, 68, 0.5);
  }
}

/* Vibrant Stock Progress Bar Styles */
.stock-critical > div {
  background: linear-gradient(90deg, #dc2626, #b91c1c);
  box-shadow: 0 0 12px rgba(220, 38, 38, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  animation: stockCriticalPulse 2s infinite;
}

.stock-danger > div {
  background: linear-gradient(90deg, #ea580c, #dc2626);
  box-shadow: 0 0 10px rgba(234, 88, 12, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  animation: stockDangerPulse 2s infinite;
}

.stock-warning > div {
  background: linear-gradient(90deg, #f59e0b, #ea580c);
  box-shadow: 0 0 8px rgba(245, 158, 11, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  animation: stockWarningGlow 3s infinite;
}

.stock-moderate > div {
  background: linear-gradient(90deg, #3b82f6, #2563eb);
  box-shadow: 0 0 6px rgba(59, 130, 246, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  animation: stockModerateShine 4s infinite;
}

.stock-excellent > div {
  background: linear-gradient(90deg, #10b981, #059669);
  box-shadow: 0 0 8px rgba(16, 185, 129, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  animation: stockExcellentGlow 3s infinite;
}

.stock-overstock > div {
  background: linear-gradient(90deg, #8b5cf6, #7c3aed);
  box-shadow: 0 0 10px rgba(139, 92, 246, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  animation: stockOverstockPulse 2.5s infinite;
}

/* Stock Progress Animations */
@keyframes stockCriticalPulse {
  0%, 100% {
    box-shadow: 0 0 12px rgba(220, 38, 38, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.2);
    transform: scaleY(1);
  }
  50% {
    box-shadow: 0 0 20px rgba(220, 38, 38, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.3);
    transform: scaleY(1.1);
  }
}

@keyframes stockDangerPulse {
  0%, 100% {
    box-shadow: 0 0 10px rgba(234, 88, 12, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  }
  50% {
    box-shadow: 0 0 16px rgba(234, 88, 12, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  }
}

@keyframes stockWarningGlow {
  0%, 100% {
    box-shadow: 0 0 8px rgba(245, 158, 11, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  }
  50% {
    box-shadow: 0 0 12px rgba(245, 158, 11, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  }
}

@keyframes stockModerateShine {
  0%, 100% {
    background: linear-gradient(90deg, #3b82f6, #2563eb);
  }
  50% {
    background: linear-gradient(90deg, #60a5fa, #3b82f6);
  }
}

@keyframes stockExcellentGlow {
  0%, 100% {
    box-shadow: 0 0 8px rgba(16, 185, 129, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  }
  50% {
    box-shadow: 0 0 15px rgba(16, 185, 129, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.4);
  }
}

@keyframes stockOverstockPulse {
  0%, 100% {
    box-shadow: 0 0 10px rgba(139, 92, 246, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  }
  50% {
    box-shadow: 0 0 18px rgba(139, 92, 246, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  }
}

/* Additional sparkle effects for progress bars */
.stock-critical, .stock-danger, .stock-warning, .stock-moderate, .stock-excellent, .stock-overstock {
  position: relative;
  overflow: hidden;
}

.stock-excellent > div::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), transparent);
  animation: stockShimmer 3s infinite;
}

@keyframes stockShimmer {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}

/* Location Performance Progress Bar Styles */
.progress-critical > div {
  background: linear-gradient(90deg, #dc2626, #b91c1c);
  box-shadow: 0 0 12px rgba(220, 38, 38, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  animation: progressCriticalPulse 2s infinite;
}

.progress-warning > div {
  background: linear-gradient(90deg, #f59e0b, #ea580c);
  box-shadow: 0 0 8px rgba(245, 158, 11, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  animation: progressWarningGlow 3s infinite;
}

.progress-moderate > div {
  background: linear-gradient(90deg, #3b82f6, #2563eb);
  box-shadow: 0 0 6px rgba(59, 130, 246, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  animation: progressModerateShine 3.5s infinite;
}

.progress-high > div {
  background: linear-gradient(90deg, #10b981, #059669);
  box-shadow: 0 0 8px rgba(16, 185, 129, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  animation: progressHighGlow 3s infinite;
}

.progress-excellent > div {
  background: linear-gradient(90deg, #8b5cf6, #7c3aed, #10b981);
  box-shadow: 0 0 12px rgba(139, 92, 246, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  animation: progressExcellentGradient 4s infinite;
}

/* Progress Performance Animations */
@keyframes progressCriticalPulse {
  0%, 100% {
    box-shadow: 0 0 12px rgba(220, 38, 38, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.2);
    transform: scaleX(1);
  }
  50% {
    box-shadow: 0 0 20px rgba(220, 38, 38, 0.8), inset 0 1px 0 rgba(255, 255, 255, 0.3);
    transform: scaleX(1.02);
  }
}

@keyframes progressWarningGlow {
  0%, 100% {
    box-shadow: 0 0 8px rgba(245, 158, 11, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  }
  50% {
    box-shadow: 0 0 14px rgba(245, 158, 11, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  }
}

@keyframes progressModerateShine {
  0%, 100% {
    background: linear-gradient(90deg, #3b82f6, #2563eb);
  }
  50% {
    background: linear-gradient(90deg, #60a5fa, #3b82f6);
  }
}

@keyframes progressHighGlow {
  0%, 100% {
    box-shadow: 0 0 8px rgba(16, 185, 129, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  }
  50% {
    box-shadow: 0 0 15px rgba(16, 185, 129, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.4);
  }
}

@keyframes progressExcellentGradient {
  0%, 100% {
    background: linear-gradient(90deg, #8b5cf6, #7c3aed, #10b981);
    box-shadow: 0 0 12px rgba(139, 92, 246, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  }
  33% {
    background: linear-gradient(90deg, #10b981, #8b5cf6, #7c3aed);
    box-shadow: 0 0 15px rgba(16, 185, 129, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.4);
  }
  66% {
    background: linear-gradient(90deg, #7c3aed, #10b981, #8b5cf6);
    box-shadow: 0 0 18px rgba(124, 58, 237, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.4);
  }
}

/* Additional sparkle effects for performance progress bars */
.progress-excellent > div::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.5), transparent);
  animation: progressShimmer 3s infinite;
}

@keyframes progressShimmer {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}

components/dashboard/Navbar.tsx:
"use client"

import { useEffect, useMemo, useRef, useState } from "react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { useTheme } from "next-themes"
import {
  Activity,
  Bell,
  Building2,
  ChevronRight,
  ExternalLink,
  Globe2,
  Menu,
  Moon,
  Search,
  ShieldCheck,
  Sun,
} from "lucide-react"

import { useShellPermissions } from "@/components/dashboard/useShellPermissions"
import { BusinessRecordSearch } from "@/components/dashboard/BusinessRecordSearch"
import { useNotifications } from "@/components/notifications/NotificationProvider"
import { Button } from "@/components/ui/button"
import { Sheet, SheetContent, SheetTrigger, SheetTitle, SheetDescription } from "@/components/ui/sheet"
import UserDropdownMenu from "@/components/UserDropdownMenu"
import {
  filterSidebarLinksByPermission,
  findSidebarActiveContext,
  getDefaultSidebarLinks,
  flattenSidebarDestinations,
  getSidebarSections,
  searchSidebarLinks,
  sidebarLinks,
} from "@/config/sidebar"
import { localizePath } from "@/i18n/routing"
import { signOut } from "@/lib/auth-client"
import { dashboardSharedCopy, localizeSidebarLinks, navigationLabel } from "@/lib/dashboard/presentation"
import { selfSignOutCopy } from "@/lib/security/self-sign-out-copy"
import { notificationCopy } from "@/lib/notifications/presentation"
import { cn } from "@/lib/utils"
import Logo from "../global/Logo"

const OrganizationBanner = ({
  organizationName,
  organizationId,
  userRole,
  locale,
}: {
  organizationName: string
  organizationId: string
  userRole: string
  locale: "en" | "fr"
}) => {
  const copy = dashboardSharedCopy[locale].shell
  const shortOrgId = organizationId ? organizationId.slice(-6).toUpperCase() : "ORG"

  return (
    <div className="hidden min-w-0 items-center gap-3 rounded-xl border border-white/10 bg-white/[0.045] px-3 py-2 text-sm shadow-[inset_0_1px_0_rgba(255,255,255,0.05)] 2xl:flex">
      <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[rgba(47,125,246,0.16)] text-[#8fb7ff]">
        <Building2 className="h-4 w-4" aria-hidden="true" />
      </div>
      <div className="min-w-0">
        <div className="flex min-w-0 items-center gap-2">
          <span className="truncate font-semibold text-white">{organizationName || copy.organization}</span>
          <span className="rounded-full bg-[rgba(45,212,191,0.14)] px-2 py-0.5 text-[0.66rem] font-bold uppercase tracking-[0.1em] text-[#7de8dc]">
            {userRole || copy.user}
          </span>
        </div>
        <div className="mt-0.5 flex items-center gap-2 text-[0.68rem] font-medium text-[#8fa4ab]">
          <Activity className="h-3 w-3 text-[#2ec98a]" aria-hidden="true" />
          <span>{copy.session}</span>
          <span className="text-white/20">/</span>
          <span>{shortOrgId}</span>
        </div>
      </div>
    </div>
  )
}

import { moduleVisibleInNavigation } from "@/lib/modules/navigation"

const Navbar = ({ session }: { session: any }) => {
  const pathname = usePathname()
  const { resolvedTheme, setTheme } = useTheme()
  const [themeReady, setThemeReady] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const [mobileSearchTerm, setMobileSearchTerm] = useState("")
  const [commandSearchTerm, setCommandSearchTerm] = useState("")
  const [signingOut, setSigningOut] = useState(false)
  const [signOutFailed, setSignOutFailed] = useState(false)
  const signOutLock = useRef(false)
  const { hasPermission } = useShellPermissions(session)
  const { soundEnabled, toggleSound } = useNotifications()
  const userRole = session?.user?.roles?.[0]?.name ?? "User"
  const localePrefix = pathname.match(/^\/(en|fr)(?=\/)/)?.[1]
  const locale = localePrefix === "fr" ? "fr" : "en"
  const copy = dashboardSharedCopy[locale].shell
  const label = (text: string) => navigationLabel(text, locale)
  const signOutText = selfSignOutCopy[locale]
  const normalizedPath = localePrefix ? pathname.replace(`/${localePrefix}`, "") : pathname
  const searchAuthority = JSON.stringify([session?.user?.id, session?.user?.organizationId, session?.user?.permissions, session?.user?.roles, session?.user?.moduleNavigation])
  useEffect(() => { setCommandSearchTerm("") }, [searchAuthority])
  const localizedHref = (href: string) => {
    if (!href.startsWith("/")) {
      return href
    }

    return localizePath(href, locale)
  }
  const targetLocale = localePrefix === "fr" ? "en" : "fr"
  const pathWithoutLocale = pathname.replace(/^\/(en|fr)(?=\/)/, "") || "/dashboard"
  const targetLocaleHref = `/${targetLocale}${pathWithoutLocale}`
  const isDarkTheme = themeReady && resolvedTheme === "dark"

  useEffect(() => {
    setThemeReady(true)
  }, [])

  const filteredLinks = useMemo(
    () => localizeSidebarLinks(filterSidebarLinksByPermission(sidebarLinks, hasPermission, (item) => moduleVisibleInNavigation(session?.user?.moduleNavigation, item)), locale),
    [hasPermission, session?.user?.moduleNavigation, locale],
  )

  const activeContext = useMemo(
    () => findSidebarActiveContext(filteredLinks, normalizedPath),
    [filteredLinks, normalizedPath],
  )

  const activeHref = activeContext?.child?.href ?? activeContext?.link.href

  const pathSegments = pathname
    .split("/")
    .filter(Boolean)
    .filter((segment) => segment !== "en" && segment !== "fr")
  const fallbackSection = pathSegments[1] ?? pathSegments[0] ?? "dashboard"
  const fallbackPageTitle = fallbackSection
    .split("-")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ")
  const pageTitle = normalizedPath === "/dashboard/access-requests" ? label("Access requests") : activeContext?.child?.title ?? activeContext?.link.title ?? fallbackPageTitle
  const breadcrumb = normalizedPath === "/dashboard/access-requests" ? pageTitle : activeContext
    ? [label(activeContext.section.title), activeContext.link.title, activeContext.child?.title]
        .filter(Boolean)
        .join(" / ")
    : pathSegments.slice(0, 3).join(" / ") || "dashboard"

  const allDestinations = useMemo(
    () => flattenSidebarDestinations(filteredLinks),
    [filteredLinks],
  )


  const commandResults = useMemo(() => {
    const query = commandSearchTerm.trim().toLowerCase()

    if (!query) {
      return []
    }

    return allDestinations
      .filter((item) =>
        item.title.toLowerCase().includes(query) ||
        item.parentTitle.toLowerCase().includes(query) ||
        item.section.title.toLowerCase().includes(query) ||
        Boolean(item.moduleSlug?.toLowerCase().includes(query)),
      )
      .slice(0, 7)
  }, [allDestinations, commandSearchTerm])

  const isMobileSearching = mobileSearchTerm.trim().length > 0

  const mobileNavigationLinks = useMemo(
    () =>
      isMobileSearching
        ? searchSidebarLinks(filteredLinks, mobileSearchTerm)
        : getDefaultSidebarLinks(filteredLinks, normalizedPath),
    [filteredLinks, isMobileSearching, mobileSearchTerm, normalizedPath],
  )

  const mobileSections = useMemo(
    () => getSidebarSections(mobileNavigationLinks),
    [mobileNavigationLinks],
  )

  const handleLogout = async () => {
    if (signOutLock.current) return
    signOutLock.current = true
    setSigningOut(true)
    setSignOutFailed(false)
    try {
      await signOut()
    } catch {
      setSignOutFailed(true)
    } finally {
      signOutLock.current = false
      setSigningOut(false)
    }
  }

  return (
    <header className="sticky top-0 z-20 isolate flex min-h-16 w-full max-w-full flex-wrap items-center gap-2 border-b border-white/10 bg-[#142129]/90 px-2 py-2 shadow-[0_20px_45px_rgba(5,12,16,0.22)] backdrop-blur-xl sm:px-4 lg:min-h-[68px] lg:px-5">
      <div className="pointer-events-none absolute inset-0 bg-[linear-gradient(180deg,rgba(255,255,255,0.055),transparent)]" />
      <Sheet open={mobileOpen} onOpenChange={setMobileOpen}>
        <SheetTrigger asChild>
          <Button variant="outline" size="icon" className="relative z-10 shrink-0 rounded-xl md:hidden">
            <Menu className="h-5 w-5" aria-hidden="true" />
            <span className="sr-only">{locale === "fr" ? "Ouvrir le menu de navigation" : "Toggle navigation menu"}</span>
          </Button>
        </SheetTrigger>
        <SheetContent side="left" closeLabel={locale === "fr" ? "Fermer la navigation" : "Close navigation"} className="dashboard-enterprise-sidebar flex w-[calc(100vw-1rem)] flex-col border-white/10 p-0 text-[#d3ddd8]">
          <SheetTitle className="sr-only">{locale === "fr" ? "Navigation de l’espace de travail" : "Workspace navigation"}</SheetTitle>
          <SheetDescription className="sr-only">{locale === "fr" ? "Recherchez une destination ou déconnectez votre session actuelle." : "Find a destination or sign out of your current session."}</SheetDescription>
          <div className="relative z-10 flex h-full min-h-0 flex-col p-4">
            <div className="mb-4 flex flex-wrap items-center gap-3 pr-8">
              <Logo variant="dark" href={localizedHref("/dashboard")} />
              <span className="max-w-full break-words rounded-full border border-white/10 bg-white/[0.055] px-2 py-1 text-[0.66rem] font-bold uppercase tracking-[0.14em] text-[#8fb7ff]">
                {mobileSections.reduce((count, section) => count + section.links.length, 0)} modules
              </span>
            </div>

            <label className="relative mb-4 block">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#7f969f]" aria-hidden="true" />
              <input
                value={mobileSearchTerm}
                onChange={(event) => setMobileSearchTerm(event.target.value)}
                placeholder={locale === "fr" ? "Rechercher des modules" : "Search modules"}
                aria-label={locale === "fr" ? "Rechercher dans la navigation mobile" : "Search mobile navigation"}
                className="h-11 w-full rounded-xl border border-white/10 bg-[#102027]/70 pl-9 pr-3 text-sm text-white outline-none placeholder:text-[#7f969f] focus:border-[#5796ff]/70 focus:ring-2 focus:ring-[#2f7df6]/20"
              />
            </label>

            <nav aria-label={locale === "fr" ? "Navigation mobile du tableau de bord" : "Mobile dashboard navigation"} className="dashboard-sidebar-scroll grid min-h-0 gap-4 overflow-y-auto text-sm font-medium">
              {mobileSections.map((section) => (
                <section key={section.key} className="grid gap-1" aria-labelledby={`mobile-sidebar-section-${section.key}`}>
                  <div className="flex items-center justify-between px-1">
                    <span id={`mobile-sidebar-section-${section.key}`} className="text-[0.64rem] font-bold uppercase tracking-[0.16em] text-[#7f969f]">
                      {label(section.title)}
                    </span>
                    <span className="text-[0.66rem] font-semibold text-[#647a83]" aria-hidden="true">
                      {section.links.length}
                    </span>
                  </div>
                  {section.links.map((link) => {
                    const Icon = link.icon
                    const destinations = link.dropdown && link.dropdownMenu?.length
                      ? link.dropdownMenu.map((item) => ({ title: item.title, href: item.href, permission: item.permission }))
                      : link.href
                        ? [{ title: link.title, href: link.href, permission: link.permission }]
                        : []

                    return destinations.map((item) => {
                      const isActive = item.href === activeHref

                      return (
                        <Link
                          key={`${link.title}-${item.href}`}
                          href={localizedHref(item.href)}
                          onClick={() => setMobileOpen(false)}
                          data-active={isActive ? "true" : "false"}
                          aria-current={isActive ? (normalizedPath === item.href ? "page" : "location") : undefined}
                          title={link.dropdown ? `${link.title}: ${item.title}` : item.title}
                          className={cn(
                            "dashboard-sidebar-module relative flex items-center gap-3 rounded-xl px-3 py-2.5 outline-none transition-all focus-visible:ring-2 focus-visible:ring-[#5796ff]/70 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0b161b]",
                          )}
                        >
                          <span className="dashboard-sidebar-module-icon flex h-8 w-8 shrink-0 items-center justify-center rounded-lg">
                            <Icon className="h-4 w-4" aria-hidden="true" />
                          </span>
                          <span className="min-w-0 flex-1 truncate">{item.title}</span>
                          <ChevronRight className="dashboard-sidebar-module-chevron h-4 w-4 shrink-0" aria-hidden="true" />
                        </Link>
                      )
                    })
                  })}
                </section>
              ))}
              {mobileSections.length === 0 ? (
                <div role="status" className="rounded-xl border border-white/10 bg-white/[0.04] px-3 py-4 text-center text-xs text-[#9fb4bb]">
                  {locale === "fr" ? "Aucun module ne correspond à votre recherche." : "No modules match your search."}
                </div>
              ) : null}
            </nav>

            <div className="mt-auto shrink-0 pt-4">
              <Button onClick={handleLogout} disabled={signingOut} size="sm" className="h-auto min-h-11 w-full whitespace-normal rounded-xl py-2">
                {signingOut ? signOutText.pending : signOutText.label}
              </Button>
              {signOutFailed && <p role="alert" className="mt-2 text-sm">{signOutText.failed}</p>}
            </div>
          </div>
        </SheetContent>
      </Sheet>
      <div className="relative z-10 hidden min-w-0 sm:block sm:max-w-[15rem] xl:max-w-[20rem]">
        <div className="flex items-center gap-2">
          <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-[rgba(47,125,246,0.16)] text-[#8fb7ff] ring-1 ring-white/10">
            <ShieldCheck className="h-4 w-4" aria-hidden="true" />
          </span>
          <h1 className="truncate text-lg font-bold text-white">{pageTitle}</h1>
        </div>
        <p className="mt-0.5 truncate text-xs font-medium text-[#8fa4ab]">{breadcrumb}</p>
      </div>
      <OrganizationBanner locale={locale} organizationName={session?.user?.organizationName ?? ""} organizationId={session.user?.organizationId ?? ""} userRole={userRole} />
      <div className="relative z-10 order-last w-full min-w-0 lg:order-none lg:w-auto lg:flex-1 xl:max-w-md 2xl:max-w-xl">
        <BusinessRecordSearch query={commandSearchTerm} onQueryChange={setCommandSearchTerm}
          locale={locale} authority={searchAuthority}
          pages={commandResults.map(item => ({ href: item.href, title: item.title, context: `${label(item.section.title)} / ${item.parentTitle}` }))} />
      </div>

      <div className="relative z-10 ml-auto flex min-w-0 max-w-full flex-wrap items-center justify-end gap-1 sm:gap-2">

        <Link
          href="/"
          className="dashboard-top-button hidden h-10 w-10 items-center justify-center rounded-xl transition-all 2xl:flex"
          target="_blank"
          rel="noreferrer"
          aria-label={copy.website}
        >
          <ExternalLink className="h-4 w-4 text-[#8fb7ff]" aria-hidden="true" />
        </Link>
        <Link
          href={targetLocaleHref}
          className="dashboard-top-button flex h-10 w-10 shrink-0 items-center justify-center gap-2 rounded-xl px-0 text-sm font-semibold uppercase transition-all sm:w-auto sm:px-3"
          aria-label={copy.switchLanguage}
          title={copy.switchLanguage}
          hrefLang={targetLocale}
        >
          <Globe2 className="h-4 w-4 text-[#8fb7ff]" aria-hidden="true" />
          <span className="hidden sm:inline">{targetLocale}</span>
        </Link>
        <button
          type="button"
          onClick={() => setTheme(isDarkTheme ? "light" : "dark")}
          className="dashboard-top-button flex h-10 w-10 shrink-0 items-center justify-center gap-2 rounded-xl px-0 text-sm font-semibold transition-all 2xl:w-auto 2xl:px-3"
          aria-label={isDarkTheme ? copy.lightTheme : copy.darkTheme}
        >
          {isDarkTheme ? (
            <Sun className="h-4 w-4 text-[#8fb7ff]" aria-hidden="true" />
          ) : (
            <Moon className="h-4 w-4 text-[#8fb7ff]" aria-hidden="true" />
          )}
          <span className="hidden 2xl:inline">{isDarkTheme ? copy.light : copy.dark}</span>
        </button>
        <button
          type="button"
          onClick={toggleSound}
          className="dashboard-top-button relative flex h-10 w-10 shrink-0 items-center justify-center rounded-xl transition-all"
          aria-label={soundEnabled ? notificationCopy[locale].disableSound : notificationCopy[locale].enableSound}
          aria-pressed={soundEnabled}
        >
          <Bell className="h-5 w-5 text-[#8fb7ff]" aria-hidden="true" />
          <span
            aria-hidden="true"
            className={cn(
              "absolute -right-1 -top-1 h-2.5 w-2.5 rounded-full",
              soundEnabled
                ? "bg-[#2ec98a] shadow-[0_0_0_4px_rgba(46,201,138,0.14)]"
                : "bg-[#7f969f] shadow-[0_0_0_4px_rgba(127,150,159,0.12)]",
            )}
          />
        </button>
        <UserDropdownMenu
          canChangePassword={hasPermission("profile.password.update")}
          username={session?.user?.name ?? ""}
          email={session?.user?.email ?? ""}
          avatarUrl={session?.user?.image ?? undefined}
          organizationName={session?.user?.organizationName ?? undefined}
          roleNames={session?.user?.roles?.map((role: { name: string }) => role.name).filter(Boolean) ?? []}
        />
      </div>
    </header>
  )
}

export default Navbar

components/dashboard/Sidebar.tsx:
"use client"

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  filterSidebarLinksByPermission,
  getDefaultSidebarLinks,
  getSidebarSections,
  findSidebarActiveContext,
  searchSidebarLinks,
  sidebarLinks,
} from "@/config/sidebar"
import { localizePath } from "@/i18n/routing"
import { signOut } from "@/lib/auth-client"
import { dashboardSharedCopy, localizeSidebarLinks, navigationLabel } from "@/lib/dashboard/presentation"
import { selfSignOutCopy } from "@/lib/security/self-sign-out-copy"
import { cn } from "@/lib/utils"
import { useShellPermissions } from "@/components/dashboard/useShellPermissions"
import {
  Activity,
  ChevronDown,
  ChevronRight,
  Crown,
  LogOut,
  Search,
} from "lucide-react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { useEffect, useMemo, useRef, useState } from "react"
import { NotificationMenu } from "../NotificationMenu"
import StoquifyLogo from "../global/kit-logo"
import { moduleVisibleInNavigation } from "@/lib/modules/navigation"

interface SidebarProps {
  session: any
  notifications?: Notification[]
}

function toSidebarDomId(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "item"
}

const Sidebar = ({ session, notifications = [] }: SidebarProps) => {
  const [signingOut, setSigningOut] = useState(false)
  const [signOutFailed, setSignOutFailed] = useState(false)
  const signOutLock = useRef(false)
  const [openDropdownKey, setOpenDropdownKey] = useState<string | null | undefined>(undefined)
  const [searchTerm, setSearchTerm] = useState("")
  const pathname = usePathname()
  const { hasPermission } = useShellPermissions(session)
  const userRole = session?.user?.roles?.[0]?.name ?? "User"
  const organizationName = session?.user?.organizationName ?? "Stoquify"
  const localePrefix = pathname.match(/^\/(en|fr)(?=\/)/)?.[1]
  const locale = localePrefix === "fr" ? "fr" : "en"
  const copy = dashboardSharedCopy[locale].shell
  const label = (text: string) => navigationLabel(text, locale)
  const signOutText = selfSignOutCopy[locale]
  const normalizedPath = localePrefix ? pathname.replace(`/${localePrefix}`, "") : pathname

  const localizedHref = (href: string) => {
    if (!href.startsWith("/")) {
      return href
    }

    return localizePath(href, locale)
  }

  // Resolve selection from all authorized links, not the current search result subset.

  const filteredLinks = useMemo(
    () => localizeSidebarLinks(filterSidebarLinksByPermission(sidebarLinks, hasPermission, (item) => moduleVisibleInNavigation(session?.user?.moduleNavigation, item)), locale),
    [hasPermission, session?.user?.moduleNavigation, locale],
  )

  const activeContext = useMemo(
    () => findSidebarActiveContext(filteredLinks, normalizedPath),
    [filteredLinks, normalizedPath],
  )
  const activeHref = activeContext?.child?.href ?? activeContext?.link.href
  const isActiveHref = (href?: string) => Boolean(href && href === activeHref)

  useEffect(() => {
    setOpenDropdownKey(undefined)
  }, [normalizedPath])

  const isSearching = searchTerm.trim().length > 0

  const defaultLinks = useMemo(
    () => getDefaultSidebarLinks(filteredLinks, normalizedPath),
    [filteredLinks, normalizedPath],
  )

  const visibleLinks = useMemo(
    () => (isSearching ? searchSidebarLinks(filteredLinks, searchTerm) : defaultLinks),
    [defaultLinks, filteredLinks, isSearching, searchTerm],
  )

  const visibleSections = useMemo(
    () => getSidebarSections(visibleLinks),
    [visibleLinks],
  )

  async function handleLogout() {
    if (signOutLock.current) return
    signOutLock.current = true
    setSigningOut(true)
    setSignOutFailed(false)
    try {
      await signOut({
        redirectTo: localizedHref("/login"),
        redirect: true,
      })
    } catch {
      setSignOutFailed(true)
    } finally {
      signOutLock.current = false
      setSigningOut(false)
    }
  }

  const userInitials = (session?.user?.name ?? "User")
    .split(" ")
    .map((part: string) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase()

  return (
    <aside
      aria-label={copy.navigation}
      className="dashboard-enterprise-sidebar fixed left-0 top-0 z-30 hidden h-full w-[220px] overflow-hidden border-r md:block lg:w-[280px]"
    >
      <div className="relative z-10 flex h-full max-h-screen flex-col">
        <div className="border-b border-white/10 px-4 py-4 lg:px-5">
          <div className="flex items-center justify-between gap-3">
            <Link
              href={localizedHref("/dashboard")}
              aria-label={copy.home}
              className="group flex min-w-0 items-center gap-3"
            >
              <StoquifyLogo theme="dark" width={180} height={52} tagline="Enterprise OS" />
            </Link>
            <div className="flex h-9 w-9 items-center justify-center rounded-lg border border-white/10 bg-white/[0.055]">
              <NotificationMenu notifications={notifications} />
            </div>
          </div>

          <div className="mt-4 rounded-xl border border-white/10 bg-white/[0.055] p-3 shadow-[inset_0_1px_0_rgba(255,255,255,0.06)]">
            <div className="flex items-center gap-3">
              <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[rgba(47,125,246,0.16)] text-[#8fb7ff]">
                <Crown className="h-4 w-4" aria-hidden="true" />
              </div>
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold text-white">{organizationName}</p>
                <div className="mt-1 flex items-center gap-2">
                  <span className="rounded-full bg-[rgba(45,212,191,0.14)] px-2 py-0.5 text-[0.66rem] font-bold uppercase tracking-[0.1em] text-[#7de8dc]">
                    {userRole}
                  </span>
                  <span className="flex items-center gap-1 text-[0.68rem] font-medium text-[#9fb4bb]">
                    <Activity className="h-3 w-3 text-[#2ec98a]" aria-hidden="true" />
                    {copy.session}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="px-4 py-4 lg:px-5">
          <label className="relative block">
            <Search
              className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#7f969f]"
              aria-hidden="true"
            />
            <input
              value={searchTerm}
              onChange={(event) => setSearchTerm(event.target.value)}
              placeholder={copy.searchModules}
              aria-label={copy.searchNavigation}
              className="h-10 w-full rounded-xl border border-white/10 bg-[#102027]/70 pl-9 pr-3 text-sm text-white outline-none placeholder:text-[#7f969f] focus:border-[#5796ff]/70 focus:ring-2 focus:ring-[#2f7df6]/20"
            />
          </label>
        </div>

        <div className="flex min-h-0 flex-1 flex-col px-2.5 pb-3 lg:px-3">
          <div className="mb-3 flex items-center justify-between px-2">
            <span className="text-[0.66rem] font-bold uppercase tracking-[0.18em] text-[#7f969f]">
              {isSearching ? copy.search : copy.modules}
            </span>
            <span
              className="rounded-full border border-white/10 bg-white/[0.05] px-2 py-0.5 text-[0.66rem] font-semibold text-[#a9b8b2]"
              aria-label={`${isSearching ? visibleLinks.length : filteredLinks.length} ${copy.modules}`}
            >
              {isSearching ? visibleLinks.length : filteredLinks.length}
            </span>
          </div>

          <nav
            aria-label="Primary dashboard modules"
            className="dashboard-sidebar-scroll grid min-h-0 min-w-0 max-w-full flex-1 items-start gap-4 overflow-y-auto overflow-x-hidden pr-1 text-sm font-medium"
          >
            {visibleSections.map((section) => (
              <section key={section.key} aria-labelledby={`sidebar-section-${section.key}`} className="grid min-w-0 gap-1">
                <div className="flex items-center justify-between px-2 pb-1">
                  <span
                    id={`sidebar-section-${section.key}`}
                    className="text-[0.64rem] font-bold uppercase tracking-[0.16em] text-[#7f969f]"
                    title={label(section.description)}
                  >
                    {label(section.title)}
                  </span>
                  <span className="text-[0.66rem] font-semibold text-[#647a83]" aria-hidden="true">
                    {section.links.length}
                  </span>
                </div>

                {section.links.map((item) => {
                  const Icon = item.icon
                  const itemKey = item.href ?? item.title
                  const submenuId = `sidebar-submenu-${toSidebarDomId(itemKey)}`
                  const isHrefIncluded = item.dropdownMenu?.some((link) => isActiveHref(link.href))
                  const isDirectActive = isActiveHref(item.href)
                  const isChildActive = Boolean(isHrefIncluded)
                  const isActive = isDirectActive || isChildActive
                  const isOpen = isSearching || openDropdownKey === itemKey || (openDropdownKey === undefined && isChildActive)
                  const isFinanceSection = item.title === "Finance"

                  return (
                    <div key={itemKey} className="min-w-0">
                      {item.dropdown ? (
                        <Collapsible open={isOpen} onOpenChange={(open) => setOpenDropdownKey(open ? itemKey : null)}>
                          <CollapsibleTrigger
                            data-active={isDirectActive ? "true" : "false"}
                            data-child-active={isChildActive ? "true" : "false"}
                            aria-controls={submenuId}
                            aria-label={`${item.title} ${copy.menu}`}
                            className={cn(
                              "dashboard-sidebar-module group relative flex w-full items-center gap-2 rounded-xl px-2.5 py-2.5 text-left outline-none transition-all duration-200 focus-visible:ring-2 focus-visible:ring-[#5796ff]/70 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0b161b]",
                            )}
                          >
                            <span className="dashboard-sidebar-module-icon flex h-8 w-8 shrink-0 items-center justify-center rounded-lg transition-colors">
                              <Icon className="h-4 w-4" aria-hidden="true" />
                            </span>
                            <span className="min-w-0 flex-1" title={item.title}>
                              <span className="block truncate">{item.title}</span>
                              {item.description ? (
                                <span className="dashboard-sidebar-module-description hidden truncate text-[0.66rem] font-medium lg:block">
                                  {item.description}
                                </span>
                              ) : null}
                            </span>
                            {item.dropdownMenu?.length ? (
                              <span
                                className="dashboard-sidebar-module-count shrink-0 rounded-full px-1.5 py-0.5 text-[0.64rem] font-semibold"
                                aria-label={`${item.dropdownMenu.length} ${copy.links}`}
                              >
                                {item.dropdownMenu.length}
                              </span>
                            ) : null}
                            {isOpen ? (
                              <ChevronDown className="dashboard-sidebar-module-chevron h-4 w-4 shrink-0" aria-hidden="true" />
                            ) : (
                              <ChevronRight className="dashboard-sidebar-module-chevron h-4 w-4 shrink-0" aria-hidden="true" />
                            )}
                          </CollapsibleTrigger>
                          <CollapsibleContent
                            id={submenuId}
                            className={cn(
                              "dashboard-sidebar-submenu mt-1 rounded-xl border py-1",
                              isFinanceSection && "dashboard-finance-submenu",
                            )}
                          >
                            {item.dropdownMenu?.map((menuItem) => {
                              const isMenuItemActive = isActiveHref(menuItem.href)

                              return (
                                <Link
                                  key={menuItem.href}
                                  href={localizedHref(menuItem.href)}
                                  data-active={isMenuItemActive ? "true" : "false"}
                                  aria-current={isMenuItemActive ? (normalizedPath === menuItem.href ? "page" : "location") : undefined}
                                  title={menuItem.title}
                                  className={cn(
                                    "dashboard-sidebar-submenu-item mx-1.5 flex items-center justify-between gap-2 rounded-lg px-2.5 py-2 text-xs outline-none transition-all focus-visible:ring-2 focus-visible:ring-[#5796ff]/70 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0e1a20]",
                                    isFinanceSection && "dashboard-finance-submenu-item",
                                  )}
                                >
                                  <span className="flex min-w-0 flex-1 items-center gap-2">
                                    <span
                                      data-active={isMenuItemActive ? "true" : "false"}
                                      className={cn(
                                        "dashboard-sidebar-submenu-dot h-1.5 w-1.5 shrink-0 rounded-full",
                                        isFinanceSection && "dashboard-finance-submenu-dot",
                                      )}
                                    />
                                    <span className="block min-w-0 flex-1 truncate">{menuItem.title}</span>
                                  </span>
                                  <span
                                    className={cn(
                                      "dashboard-sidebar-submenu-action flex h-5 w-5 shrink-0 items-center justify-center rounded-full",
                                      isFinanceSection && "dashboard-finance-submenu-action",
                                    )}
                                  >
                                    <ChevronRight className="h-3 w-3" aria-hidden="true" />
                                  </span>
                                </Link>
                              )
                            })}
                          </CollapsibleContent>
                        </Collapsible>
                      ) : (
                        <Link
                          href={localizedHref(item.href ?? "#")}
                          data-active={isActive ? "true" : "false"}
                          aria-current={isActive ? (normalizedPath === item.href ? "page" : "location") : undefined}
                          title={item.title}
                          className={cn(
                            "dashboard-sidebar-module group relative flex items-center gap-2 rounded-xl px-2.5 py-2.5 outline-none transition-all duration-200 focus-visible:ring-2 focus-visible:ring-[#5796ff]/70 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0b161b]",
                          )}
                        >
                          <span className="dashboard-sidebar-module-icon flex h-8 w-8 shrink-0 items-center justify-center rounded-lg">
                            <Icon className="h-4 w-4" aria-hidden="true" />
                          </span>
                          <span className="min-w-0 flex-1">
                            <span className="block truncate">{item.title}</span>
                            {item.description ? (
                              <span className="hidden truncate text-[0.66rem] font-medium text-[#7f969f] lg:block">
                                {item.description}
                              </span>
                            ) : null}
                          </span>
                        </Link>
                      )}
                    </div>
                  )
                })}
              </section>
            ))}
            {visibleLinks.length === 0 && (
              <div role="status" className="rounded-xl border border-white/10 bg-white/[0.04] px-3 py-4 text-center text-xs text-[#9fb4bb]">
                {copy.emptySearch}
              </div>
            )}
          </nav>
        </div>

        <div className="border-t border-white/10 p-3 lg:p-4">
          <div className="flex items-center gap-3 rounded-xl border border-white/10 bg-[#0e1a20]/70 p-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-[#2563eb] to-[#5796ff] text-sm font-black text-white shadow-lg">
              {userInitials}
            </div>
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-semibold text-white">{session?.user?.name ?? "User"}</p>
              <p className="truncate text-xs text-[#8fa4ab]">{session?.user?.email ?? ""}</p>
            </div>
            <button
              type="button"
              onClick={handleLogout}
              disabled={signingOut}
              className="dashboard-top-button flex h-9 w-9 shrink-0 items-center justify-center rounded-lg transition-all"
              aria-label={signingOut ? signOutText.pending : signOutText.label}
            >
              <LogOut className="h-4 w-4" aria-hidden="true" />
            </button>
          </div>
          {signOutFailed && <p role="alert" className="mt-2 text-sm">{signOutText.failed}</p>}
        </div>
      </div>
    </aside>
  )
}

